LAYER
    NAME "asap_cropland"
    TYPE RASTER
    STATUS ON
    DATA "/opt/rasterdata/landcover/asap_cropland_gha.tif"
    MASK "gha_admin_extent_mask"
    PROCESSING "NODATA=0"
    PROJECTION
        "init=epsg:4326"
    END
    INCLUDE "classifications/asap-cropland.classes.map"
    METADATA
        "wms_title" "ASAP Cropland Mask v02"
        "wms_abstract" "JRC ASAP cropland mask v02 (~1 km resolution). Values represent percentage of cropland cover per pixel. Source: European Commission Joint Research Centre (JRC)."
        INCLUDE "shared/wms-layer-metadata.map"
    END
END
